module tb_TopModule;
    reg in1;
    reg in2;
    wire out;

    TopModule dut (
        .in1(in1),
        .in2(in2),
        .out(out)
    );

    initial begin
        // Test all 4 input combinations for NOR gate
        in1 = 0; in2 = 0; #10;
        if (out !== 1'b1) begin
            $display("SELFTEST FAIL: in1=0, in2=0 expected out=1, got %b", out);
            $finish;
        end

        in1 = 0; in2 = 1; #10;
        if (out !== 1'b0) begin
            $display("SELFTEST FAIL: in1=0, in2=1 expected out=0, got %b", out);
            $finish;
        end

        in1 = 1; in2 = 0; #10;
        if (out !== 1'b0) begin
            $display("SELFTEST FAIL: in1=1, in2=0 expected out=0, got %b", out);
            $finish;
        end

        in1 = 1; in2 = 1; #10;
        if (out !== 1'b0) begin
            $display("SELFTEST FAIL: in1=1, in2=1 expected out=0, got %b", out);
            $finish;
        end

        $display("SELFTEST PASS");
        $finish;
    end
endmodule
